message.content:
{
  "candidate_edge_types": [
    {
      "name": "PROGRESS_OBSERVATION_GUIDES_NEXT_MONITORING_ACTION",
      "definition": "An earlier observation that reports the current progress state of a long-running execution is used to determine the timing and content of a subsequent status-check action on that same execution.",
      "source_description": "An observation reporting the progress of an ongoing execution (e.g., completed iteration, loss value, or elapsed timestamp).",
      "target_description": "A subsequent agent action that waits and re-checks the status of that same ongoing execution."
    },
    {
      "name": "OBSERVED_MILESTONE_VALIDATES_PRIOR_ESTIMATE",
      "definition": "A later observation reports a milestone that matches a previously stated estimate about when that milestone would occur, confirming the execution is advancing as predicted.",
      "source_description": "A previously stated estimate or expectation about upcoming execution progress.",
      "target_description": "A subsequent observation that reports the predicted milestone, confirming the estimate."
    },
    {
      "name": "UNCHANGED_PROGRESS_PROMPTS_REPEATED_RECHECK",
      "definition": "An observation indicating that a monitored execution has not yet produced a new milestone or reached completion triggers another equivalent wait-and-recheck action.",
      "source_description": "An observation showing the monitored execution is still running without having reached its next milestone.",
      "target_description": "A subsequent agent action that repeats the wait-and-recheck on the same execution."
    }
  ]
}

